WITH flattened_attrs AS (SELECT id, effective_from, currency, tier_prices, discounts, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ARRAY_MIN(tier_prices) AS lowest_price, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ZIP_WITH(tier_prices, discounts, (p, d) -> ROUND(p * (1 - d), 2)) AS net_prices FROM price_tiers WHERE currency IN ('THB', 'EUR')) SELECT currency, ROUND(AVG(lowest_price), 2) AS avg_lowest_price, PERCENTILE_APPROX(avg_tier_price, ARRAY(0.25, 0.5, 0.75)) AS avg_tier_price_quartiles, COUNT(DISTINCT currency) AS distinct_currencies, GROUPING_ID() AS grouping_level FROM flattened_attrs GROUP BY CUBE (currency);
